function jobCards(jobs){return `<div class="job-queue">${jobs.map(j=>{const c=db.cars.find(c=>c.id===j.carId),image=ShowroomModel.photos(c)[0],general=j.kind==='general',category=JobTypes.get(j.category),status=j.status==='active'&&jobPlan(j.id).waiting?'Waiting for parts':{active:'Active',completed:'Completed',cancelled:'Cancelled'}[j.status],note=j.log.filter(e=>e.action!=='job.edit').at(-1)?.note||j.notes||(general?'No work instructions added yet.':'Work towards the saved configuration.');return `<article class="job-queue-card ${general?'general-job':'setup-job'} job-tone-${category.tone} ${j.status}" data-action="open-job" data-id="${esc(j.id)}" aria-label="${j.status==='active'?'Resume':'View'} ${esc(j.name)} for ${esc(c.name)}"><span class="job-queue-top"><span class="job-kind">${icon(category.icon)}${category.label}</span><span class="job-status ${j.status} ${j.status==='active'&&jobPlan(j.id).waiting?'waiting':''}">${status}</span></span><span class="job-queue-identity"><span class="job-car-photo">${image?`<img src="${esc(thumbnailSource(image.data))}" alt="" loading="lazy">`:icon('car')}</span><span class="job-queue-names"><strong class="job-car-name">${esc(c.name)}</strong><span class="job-name">${esc(j.name)}</span>${general?'':'<span class="tiny muted">Saved setup plan</span>'}${c.number?`<span class="tiny muted">${esc(c.number)}</span>`:''}</span></span><span class="job-preview">${esc(note)}</span>${jobPlanBadges(j)}<span class="job-queue-footer"><span class="tiny muted">Updated ${date(j.updated)}</span><span class="actions">${j.status==='active'?btn('Edit','edit-job','small',j.id):''}${btn(j.status==='active'?'Resume job →':'View record →','open-job','small',j.id)}</span></span></article>`;}).join('')}</div>`}
let workshopJob=null,recentWorkLimit=3,jobCategory='';
function jobCategoryField(value='general'){return '<label class="field wide">Category<select name="category">'+JobTypes.types.map(t=>'<option value="'+t.id+'" '+(t.id===value?'selected':'')+'>'+t.label+'</option>').join('')+'</select></label>';}
function jobCategoryFilter(){return '<label class="field job-category-filter">Category<select id="job-category-filter"><option value="">All categories</option>'+JobTypes.types.map(t=>'<option value="'+t.id+'" '+(jobCategory===t.id?'selected':'')+'>'+t.label+'</option>').join('')+'</select></label>';}
function editWorkshopJob(id){
  const j=db.jobs.find(j=>j.id===id),revision=db.revision;
  if(!j||j.status!=='active'){toast('This job is already closed or missing.',true);return;}
  modal('Edit workshop job',`<div class="form-grid"><label class="field wide">Job name<input name="name" value="${esc(j.name)}" maxlength="200" required></label>${jobCategoryField(j.category)}<label class="field wide">Planned work / instructions<textarea name="notes" maxlength="20000">${esc(j.notes||'')}</textarea></label></div>${dl([['Car',db.cars.find(c=>c.id===j.carId).name],['Work plan',j.kind==='general'?'Free-form work':('Saved setup · '+j.target.name)]])}<p class="muted mt">The car, setup target and recorded progress stay attached to this job.</p>`,async values=>{await change('job.edit',{id,revision,name:values.name,notes:values.notes,category:values.category});if(workshopJob?.job.id===id)await refreshJob();},'Save changes');
}
async function openJob(id){workshopJob=await api('plan','job.view',{id});toolboxTab='Jobs';page='Workshop';render();}
async function refreshJob(){if(workshopJob)workshopJob=await api('plan','job.view',{id:workshopJob.job.id});}
function jobOverview(){
  if(db._view?.jobCounts){const counts=db._view.jobCounts;return `<section class="workshop-queue"><div class="job-queue-heading"><h2>${closedJobs?'Completed & cancelled jobs':'Active jobs'} <span class="badge">${closedJobs?counts.closed:counts.active}</span></h2><div class="actions job-queue-controls">${jobCategoryFilter()}${btn(closedJobs?'Show active jobs':'Completed & cancelled ('+counts.closed+')','query-closed-jobs')}</div></div>${db.jobs.length?jobCards(db.jobs):'<div class="panel"><p class="muted">No jobs here.</p></div>'}${viewPager(db._view.list)}</section>`;}
  const jobs=db.jobs.filter(j=>!jobCategory||(j.category||'general')===jobCategory),active=jobs.filter(j=>j.status==='active'),closed=jobs.filter(j=>j.status!=='active');

  return `<section class="workshop-queue"><div class="job-queue-heading"><h2>Active jobs <span class="badge">${active.length}</span></h2>${jobCategoryFilter()}<p class="muted">Choose a car’s job to continue its work.</p></div>${active.length?jobCards(active):'<div class="panel"><p class="muted">No active jobs. Start one with New workshop job.</p></div>'}${closed.length?`<details class="job-history"><summary>Completed & cancelled jobs <span class="badge">${closed.length}</span></summary>${jobCards(closed)}</details>`:''}</section>`;
}
function snapshotDetails(snap){return `${dl([...Object.entries(snap.technical).filter(([,v])=>v).map(([k,v])=>[techLabels[k]||k,v]),...ratioRows(snap.technical)])}<h3 class="mt">Fitted inventory at this point</h3>${(snap.installations||[]).map(i=>`<p>${esc(i.name)} · ${i.quantity} piece(s) · ${esc(techLabels[i.field]||i.position)}</p>`).join('')||'<p class="muted">'+(snap.installations?'No tracked inventory fitted.':'This earlier record has no inventory snapshot.')+'</p>'}`;}
function renderJob(){
  const m=workshopJob,j=m.job;
  let head=heading(j.name,`${m.carName} · ${JobTypes.get(j.category).label} · ${j.status}`,(j.status==='active'?btn(icon('edit')+' Edit details','edit-job','',j.id):'')+btn('All workshop jobs','jobs-back'));
  if(m.revision!==db.revision)return head+panel('The database changed',`<p>Recheck the current car and available parts before continuing.</p>${btn('Refresh job','open-job','primary',j.id)}`);
  head+=rebuildJobCard(j)+jobPlanningPanel(j);
  if(j.status==='active'&&j.kind!=='general')head+=`<div class="note info mt">${btn('Update shopping requirements','job-shopping','',j.id)}<p>Calculate missing loose parts for all outstanding setup steps. Fitted substitutes count as completed. Assemblies need an explicit choice; they are not ordered automatically. Plans share available stock and do not reserve it.</p></div>`;
  if(j.kind==='general')return renderGeneralJobDesign(m,head);
  if(j.status!=='active')return head+`<div class="note info">${j.status==='completed'?'Completed':'Cancelled'} ${date(j.finished)}. This record preserves the actual configuration when the job closed.</div><div class="two-col mt">${panel('Actual configuration',snapshotDetails(j.actual))}${panel('Original target',snapshotDetails(j.target))}</div>`+jobLog(j);
  const uniqueExtras=m.extras.filter((i,index,all)=>!i.assemblyId||all.findIndex(x=>x.assemblyId===i.assemblyId)===index);
  return head+(j.notes?panel('Planned work',`<p class="prewrap">${esc(j.notes)}</p>`):'')+`<div class="note info mt"><strong>${m.remaining} outstanding step${m.remaining===1?'':'s'}</strong> · Progress is saved after each confirmed change. The car’s current configuration always describes what is actually fitted. You can leave this page and resume later.</div><div class="actions mt">${btn('Record test of current car','add-test','',j.carId)}${m.remaining===0?btn('Complete job…','finish-job','primary',j.id):''}${btn('Cancel job…','cancel-job','',j.id)}</div>`+
    `<div class="two-col mt">${panel('Target components',m.rows.length?m.rows.map(r=>`<section class="job-step"><div class="row">${badge(r.done?'Fitted':'Outstanding',r.done?'good':'')}<strong>${esc(r.name)}</strong></div><p class="tiny muted">${r.kind==='assembly'?'Complete assembly':r.quantity+' piece(s) · '+esc(techLabels[r.field]||r.position)}</p><p>${r.done?'Actually fitted: '+esc(r.actual):'Choose available stock or record an already fitted substitute.'}</p>${btn(r.done?'Review / change…':'Fit / confirm…','job-fit','small',r.key)}${r.done?btn('Return to used spares…','job-remove','small',r.installationIds[0]):''}</section>`).join(''):'<p class="muted">No tracked components in the target.</p>')}${panel('Fitted parts still to resolve',uniqueExtras.length?uniqueExtras.map(i=>`<section class="job-step"><strong>${esc(i.assemblyId?db.assemblies.find(a=>a.id===i.assemblyId)?.name:i.name)}</strong><p class="tiny muted">${i.assemblyId?'Complete assembly':i.quantity+' piece(s) · '+esc(techLabels[i.field]||i.position)}</p><p class="tiny muted">Confirm it against a target step if it is a substitute, or return it to used spares. Clear occupied positions before fitting replacements.</p>${btn('Return to used spares…','job-remove','small',i.id)}</section>`).join(''):'<p class="muted">No extra tracked inventory to resolve.</p>')}</div>`+
    `<div class="mt">${panel('Settings and untracked specifications',m.settings.length?`<div class="table-wrap"><table><thead><tr><th>Setting</th><th>Actual car</th><th>Target</th><th>Status</th></tr></thead><tbody>${m.settings.map(s=>`<tr><td>${esc(techLabels[s.key]||s.key)}</td><td>${esc(s.actual||'—')}</td><td>${esc(s.target||'—')}</td><td>${s.done?badge('Matches','good'):btn('Record adjustment…','job-setting','small',s.key)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No other settings to check.</p>')}</div>`+jobLog(j);
}
function jobLog(j){return `<div class="mt">${panel('Recorded work',j.log.length?j.log.slice().reverse().map(e=>`<div class="list-row"><div><strong>${esc(e.note)}</strong><div class="tiny muted">${date(e.date)}</div></div></div>`).join(''):'<p class="muted">No physical changes recorded for this job yet.</p>')}</div>`;}
function startJob(id){const s=db.setups.find(s=>s.id===id),revision=db.revision;modal('Start staged setup job',`<p>Use <strong>${esc(s.name)}</strong> as the target for ${esc(db.cars.find(c=>c.id===s.carId).name)}.</p><p>You can complete parts and settings in separate sessions. Starting the job does not move stock or change the car.</p>${jobCategoryField()}`,async values=>{const jobId=await change('job.start',{setupId:id,revision,category:values.category});workshopJob=await api('plan','job.view',{id:jobId});toolboxTab='Jobs';page='Workshop';},'Start job');}
function newWorkshopJob(preferredCarId,task=''){
  const cars=db.cars.filter(slotforgeDomain.activeCar),revision=db.revision;
  if(!cars.length){modal('Add a car first',`<p>A workshop job belongs to a car in your collection.</p>${btn('Add car','add-car','primary')}`,null);return;}
  const busy=id=>db.jobs.some(j=>j.carId===id&&j.status==='active'),first=cars.find(c=>c.id===preferredCarId&&!busy(c.id))||cars.find(c=>!busy(c.id));
  if(!first){modal('Your cars already have active jobs','<p>Resume or close an existing job before starting another for the same car.</p>',null);return;}
  modal('New workshop job',`<div class="form-grid"><label class="field wide">Car<select name="carId" id="job-car" required>${cars.map(c=>`<option value="${esc(c.id)}" ${c.id===first.id?'selected':''} ${busy(c.id)?'disabled':''}>${esc(c.name)}${busy(c.id)?' · Active job already':''}</option>`).join('')}</select></label>${jobCategoryField(task?'maintenance':'general')}<label class="field wide">Work plan<select name="kind" id="job-kind"><option value="general">Free-form work</option><option value="setup">Work towards a saved setup</option><option value="rebuild">Rebuild into a linked new car</option></select></label><div class="field wide" id="general-job-fields"><label class="field">Job name<input name="name" maxlength="200" required placeholder="For example: Replace braids and clean motor"></label>${field('notes','Planned work / instructions','','textarea')}</div><div class="field wide" id="setup-job-fields" hidden></div></div><p class="muted mt">Starting a job records your plan. It does not change the car or move stock. You can leave and resume the job later.</p>`,async values=>{if(values.kind==='rebuild'){const draftId=await change('rebuild.start',{revision,carId:values.carId,name:values.name,notes:values.notes});await openRebuildDraft(draftId);return;}const id=await change('job.start',{revision,...values});workshopJob=await api('plan','job.view',{id});toolboxTab='Jobs';page='Workshop';},'Start job');
  if(task)$('#dialog [name=name]').value=task.slice(0,200);
  updateJobChoices();
}
function updateJobChoices(){
  const general=$('#job-kind').value!=='setup',car=$('#job-car').value,setups=db.setups.filter(s=>s.carId===car);
  $('#job-rebuild-warning')?.remove();if(buildDirty&&$('#job-kind').value==='rebuild')$('#general-job-fields').insertAdjacentHTML('beforeend','<p id="job-rebuild-warning" class="note">Opening this rebuild will replace your unsaved builder selections. Cancel and save your current draft first to keep them.</p>');
  $('#general-job-fields').hidden=!general;for(const el of $('#general-job-fields').querySelectorAll('input,textarea'))el.disabled=!general;
  $('#setup-job-fields').hidden=general;$('#setup-job-fields').innerHTML=`<label class="field">Saved setup<select name="setupId" ${general?'disabled':'required'}><option value="">Choose a setup</option>${setups.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${date(s.date)}</option>`).join('')}</select></label>${setups.length?'':'<p class="muted">This car has no saved setups. Use General work, or save a configuration from the car’s Setups section first.</p>'}`;
}
function recordJobProgress(){const {job,revision}=workshopJob;modal('Record job progress',field('note','Work performed / observations','','textarea')+'<p class="muted">This adds to the job history. Update physical parts and specifications on the car page when needed.</p>',async values=>{await change('job.note',{id:job.id,revision,note:values.note});await refreshJob();},'Save progress');}
document.addEventListener('change',event=>{if(event.target.id==='job-category-filter'){jobCategory=event.target.value;render();return;}if(event.target.name==='category'&&$('#job-kind')){if(event.target.value==='rebuild')$('#job-kind').value='rebuild';else if($('#job-kind').value==='rebuild')$('#job-kind').value='general';updateJobChoices();}if(['job-kind','job-car'].includes(event.target.id)){if($('#job-kind').value==='rebuild')$('#dialog [name=category]').value='rebuild';updateJobChoices();}});
function jobAction(action,key){
  const m=workshopJob,j=m.job,payload={id:j.id,revision:m.revision},confirm=`<label class="check-row mt"><input type="checkbox" name="confirmed" required>I have made and checked this physical change.</label>`;
  let title,body;
  if(action==='job-fit'){
    const r=m.rows.find(r=>r.key===key);title='Fit / confirm · '+r.name;payload.key=key;
    body=`<p>Target: <strong>${esc(r.name)}</strong>. Existing components in an occupied position must be returned first.</p><label class="field">Actual component or assembly<select name="selection" required><option value="">Choose stock or an installed item</option>${r.choices.map(c=>`<option value="${esc(c.value)}" ${r.selected===c.value?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label><label class="check-row mt"><input type="checkbox" name="allowTransfer">If this item is on another car, I confirm its physical transfer.</label>${confirm}`;
  }else if(action==='job-remove'){
    const i=m.actual.installations.find(i=>i.id===key);title='Return fitted stock';payload.installationId=key;
    body=`<p>Return <strong>${esc(i.assemblyId?db.assemblies.find(a=>a.id===i.assemblyId).name:i.name)}</strong> to Used spares. ${i.assemblyId?'The complete assembly stays together.':'Quantity stock is kept separate from unused stock.'}</p>${confirm}`;
  }else if(action==='job-setting'){
    const s=m.settings.find(s=>s.key===key);title='Record adjustment';payload.key=key;
    body=dl([['Setting',techLabels[key]||key],['Current',s.actual||'—'],['Target',s.target||'—']])+confirm;
  }else{
    title=action==='finish-job'?'Complete workshop job':'Cancel workshop job';
    body=`<p>${action==='finish-job'?(j.kind==='general'?'Mark the planned work complete and save the car’s current configuration as the finished result.':'Save the actual configuration as the finished result. The original target remains unchanged.'):'Close this job. All recorded physical changes stay on the car; cancelling does not undo work or move stock.'}</p><label class="check-row mt"><input type="checkbox" name="confirmed" required>${action==='finish-job'?'I have checked the finished car.':'I understand that completed work will remain.'}</label>`;
  }
  const operation={'job-fit':'job.fit','job-remove':'job.remove','job-setting':'job.setting','finish-job':'job.complete','cancel-job':'job.cancel'}[action];
  modal(title,body,async values=>{await change(operation,{...payload,...values,confirmed:!!values.confirmed,allowTransfer:!!values.allowTransfer});await refreshJob();},'Record');
}
function replaceAssemblyDialog(id){
  const a=liveAssemblies().find(a=>a.id===id),revision=db.revision;
  modal('Replace an assembly component',`<p><strong>${esc(a.name)}</strong> · ${a.carId?'Installed on '+esc(db.cars.find(c=>c.id===a.carId).name):'In storage'}</p><p>Keep the group together and replace one member. The replacement uses the same quantity and position. The removed component returns to used spares; saved setups keep their original parts.</p><label class="field">Component to remove<select name="componentId">${a.components.map(c=>`<option value="${c.partId}">${esc(db.parts.find(p=>p.id===c.partId).name)} · ${c.quantity} piece(s) · ${esc(techLabels[c.field]||c.position)}</option>`).join('')}</select></label><label class="field">Replacement stock<select name="partId" required><option value="">Choose available stock</option>${db.parts.filter(p=>available(p)>0).map(p=>`<option value="${p.id}">${esc(componentLabel(p))} · ${available(p)} free · ${esc(p.condition)}</option>`).join('')}</select></label>${field('location','Removed component location','Used spares')}<label class="check-row mt"><input name="confirmed" type="checkbox" required>I have physically replaced this component.</label>`,async values=>change('assembly.replace',{id,revision,...values,confirmed:!!values.confirmed}),'Record replacement');
}

function renderRecentWork(){
  const events=db.events.filter(e=>['maintenance','modification','installation','removal'].includes(e.type));
  const shown=Math.min(recentWorkLimit,events.length),total=db._view?.recentTotal??events.length;
  return timeline(events.slice(0,shown))+(total>3?'<div class="recent-work-footer"><p class="tiny muted" role="status">Showing '+shown+' of '+events.length+' entries</p><div class="actions">'+(shown<total&&recentWorkLimit<200?btn('Show more','recent-work-more','small'):'')+(recentWorkLimit>3?btn('Show less','recent-work-less','small'):'')+'</div></div>':'');
}
